// What a drawing is once read (D-1398): the shapes and arrows the native library loaded, in the drawing's own coordinates. The drawing
// viewer hands it to `onRead`, so an app can describe a drawing to a model without parsing the file again. This module is cheap: it
// loads neither Excalidraw nor the draw.io viewer, which the viewer imports only when a drawing of that format opens.

/** The two formats: an Excalidraw scene (JSON) and a draw.io file (XML, plain or compressed). */
export type DrawingFormat = 'excalidraw' | 'drawio';

/** A shape: its kind in the native vocabulary (Excalidraw `rectangle`, `ellipse`, `diamond`, `text`, `freedraw`, …; draw.io `rectangle`, `ellipse`, `rhombus`, `swimlane`, …). */
export interface DrawingShape {
  readonly id: string;
  readonly kind: string;
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  /** Degrees clockwise around the box's centre, when the shape is turned (x, y, width and height are the unturned box). */
  readonly rotation?: number | undefined;
  /** Its text: a container's bound text, or a text element's own; HTML stripped. */
  readonly label?: string | undefined;
  readonly stroke?: string | undefined;
  readonly fill?: string | undefined;
  /** The group or container it sits in, when there is one. */
  readonly parent?: string | undefined;
}

/** An arrow or a line: the shapes it joins (absent when an end is free) and its points, from start to end, on their outlines. */
export interface DrawingArrow {
  readonly id: string;
  readonly kind: 'arrow' | 'line';
  readonly from?: string | undefined;
  readonly to?: string | undefined;
  readonly points: readonly (readonly [number, number])[];
  readonly label?: string | undefined;
  readonly stroke?: string | undefined;
}

export interface Drawing {
  readonly format: DrawingFormat;
  /** The bounds of everything drawn, in the drawing's coordinates. */
  readonly bounds: { readonly x: number; readonly y: number; readonly width: number; readonly height: number };
  readonly shapes: readonly DrawingShape[];
  readonly arrows: readonly DrawingArrow[];
}

/** The format of a file by its name (`.excalidraw`, `.excalidraw.json`, `.drawio`, `.drawio.xml`, `.dio`), else by its text. */
export function drawingFormat(path: string | undefined, text?: string): DrawingFormat | undefined {
  const name = (path ?? '').toLowerCase();
  if (/\.excalidraw(?:\.json)?$/.test(name)) return 'excalidraw';
  if (/\.(?:drawio(?:\.xml)?|dio)$/.test(name)) return 'drawio';
  const start = (text ?? '').trimStart();
  if (start.startsWith('{') && /"type"\s*:\s*"excalidraw"/.test(start.slice(0, 400))) return 'excalidraw';
  if (start.startsWith('<') && /<(?:mxfile|mxGraphModel|diagram)\b/.test(start.slice(0, 8000))) return 'drawio';
  return undefined;
}

/** Whether a path names a drawing file. */
export const isDrawingPath = (path: string): boolean => drawingFormat(path) !== undefined;

const round = (value: number) => Math.round(value);
const name = (drawing: Drawing, id: string | undefined) => {
  if (!id) return 'nothing';
  const shape = drawing.shapes.find(entry => entry.id === id);
  return shape ? (shape.label ? `"${shape.label}"` : `${shape.kind} ${id}`) : id;
};

/** A plain-text account of a drawing for a model: every shape with its place, size, label and colours, then every arrow with its ends. */
export function describeDrawing(drawing: Drawing): string {
  const lines = [`A ${drawing.format === 'drawio' ? 'draw.io' : 'Excalidraw'} drawing of ${drawing.shapes.length} shapes and ${drawing.arrows.length} arrows, ${round(drawing.bounds.width)}×${round(drawing.bounds.height)}.`];
  for (const shape of drawing.shapes) {
    const colours = [shape.stroke && `stroke ${shape.stroke}`, shape.fill && `fill ${shape.fill}`].filter(Boolean).join(', ');
    lines.push(`- ${shape.kind} ${shape.id}${shape.label ? ` "${shape.label}"` : ''} at (${round(shape.x)}, ${round(shape.y)}), ${round(shape.width)}×${round(shape.height)}${colours ? `, ${colours}` : ''}${shape.parent ? `, in ${name(drawing, shape.parent)}` : ''}`);
  }
  for (const arrow of drawing.arrows) lines.push(`- ${arrow.kind} ${arrow.id}${arrow.label ? ` "${arrow.label}"` : ''} from ${name(drawing, arrow.from)} to ${name(drawing, arrow.to)}`);
  return lines.join('\n');
}

/** Why a drawing could not be shown: the file is not one (`unreadable`), it draws nothing (`empty`) or the native renderer failed (`renderer`). */
export type DrawingFailure = 'unreadable' | 'empty' | 'renderer';

export class DrawingError extends Error {
  readonly reason: DrawingFailure;
  constructor(reason: DrawingFailure, message?: string) { super(message ?? reason); this.name = 'DrawingError'; this.reason = reason; }
}

/** A drawing as the native library drew it: an SVG document (shown as an image, so nothing in it runs) and what it read. */
export interface RenderedDrawing {
  readonly svg: string;
  readonly width: number;
  readonly height: number;
  readonly drawing: Drawing;
  /** What the renderer was refused (a draw.io image, stencil or font from the network): those parts are not drawn. */
  readonly blocked: readonly string[];
}

/** The bounds of boxes, or an empty box at the origin. */
export function boundsOf(boxes: readonly { readonly x: number; readonly y: number; readonly width: number; readonly height: number }[]): Drawing['bounds'] {
  if (!boxes.length) return { x: 0, y: 0, width: 0, height: 0 };
  const left = Math.min(...boxes.map(box => box.x)), top = Math.min(...boxes.map(box => box.y));
  const right = Math.max(...boxes.map(box => box.x + box.width)), bottom = Math.max(...boxes.map(box => box.y + box.height));
  return { x: left, y: top, width: right - left, height: bottom - top };
}

/* The drawing viewer's words in English and French. `locale` picks the base set; a host's `labels` still override any of them. */
import type { DrawingFailure, DrawingFormat } from './drawing';

export type DrawingLocale = 'en' | 'fr';

export const defaultDrawingLabels = {
  /** The kind's name on the artifact card and in the panel bar. */
  kind: 'Drawing',
  loading: 'Drawing…',
  /** The image's text alternative. */
  image: (format: DrawingFormat, shapes: number, arrows: number) => `${format === 'drawio' ? 'draw.io' : 'Excalidraw'} drawing: ${shapes} shapes, ${arrows} arrows`,
  errorTitle: 'This drawing cannot be shown',
  error: (reason: DrawingFailure) => reason === 'unreadable' ? 'The file is not an Excalidraw (.excalidraw) or draw.io (.drawio) drawing, or it is damaged.'
    : reason === 'empty' ? 'The drawing is empty: there is nothing to draw.' : 'The drawing could not be drawn. Try opening it again.',
};
export type DrawingLabels = typeof defaultDrawingLabels;

/** Typed as `DrawingLabels`, so a key added in English must be added here too. */
export const frenchDrawingLabels: DrawingLabels = {
  kind: 'Dessin',
  loading: 'Dessin en cours…',
  image: (format, shapes, arrows) => `Dessin ${format === 'drawio' ? 'draw.io' : 'Excalidraw'} : ${shapes} formes, ${arrows} flèches`,
  errorTitle: 'Ce dessin ne peut pas être affiché',
  error: reason => reason === 'unreadable' ? 'Le fichier n’est pas un dessin Excalidraw (.excalidraw) ou draw.io (.drawio), ou il est abîmé.'
    : reason === 'empty' ? 'Le dessin est vide : il n’y a rien à dessiner.' : 'Le dessin n’a pas pu être tracé. Rouvrez-le.',
};

/** The viewer's words for `locale` (English by default) with the host's overrides. */
export const drawingLabelsFor = (locale: DrawingLocale | undefined, labels?: Partial<DrawingLabels>): DrawingLabels =>
  ({ ...(locale === 'fr' ? frenchDrawingLabels : defaultDrawingLabels), ...labels });

// An Excalidraw scene drawn by Excalidraw itself (D-1398): `restore` (the library's own reader: defaults, migrations, bound text) then
// `exportToSvg` on a white page, so the drawing has Excalidraw's hand-drawn strokes, fills and fonts. The library loads with this module,
// which the viewer imports only when an Excalidraw file opens. Fonts come from the app (`assets`, the folder that serves Excalidraw's
// `dist/prod/fonts`). Excalidraw falls back to its CDN (esm.sh) for a font it cannot get from there; while an export runs, this module
// refuses the CDN (a font fetch, and the CDN sources of the font faces it creates), so a drawing never fetches from it; an export that fails is drawn
// again without fonts. The page's `fetch` and `FontFace` are given back as they were once no drawing is being made.
import type { DrawingArrow, DrawingShape, RenderedDrawing } from './drawing';
import { DrawingError } from './drawing';

declare global { interface Window { EXCALIDRAW_ASSET_PATH?: string | string[] } }

/** The fields of an Excalidraw element this module reads (the library's element type, structurally). */
interface Element {
  readonly id: string;
  readonly type: string;
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly angle?: number;
  readonly isDeleted?: boolean;
  readonly strokeColor?: string;
  readonly backgroundColor?: string;
  readonly frameId?: string | null;
  readonly containerId?: string | null;
  readonly text?: string;
  readonly originalText?: string;
  readonly points?: readonly (readonly [number, number])[];
  readonly startBinding?: { readonly elementId: string } | null;
  readonly endBinding?: { readonly elementId: string } | null;
}

type Point = readonly [number, number];

const FONT_PROBE = 'fonts/Virgil/Virgil-Regular.woff2';
/** Where Excalidraw 0.18 falls back for its fonts (`ExcalidrawFontFace.ASSETS_FALLBACK_URL`). */
const FONT_CDN = /^https:\/\/esm\.sh\/@excalidraw\/excalidraw(?:@|\/)/;
const colour = (value: string | undefined) => value && value !== 'transparent' ? value : undefined;

/** A `FontFace` source list without Excalidraw's CDN entries (`url(https://esm.sh/@excalidraw/…) format('woff2')`). */
function withoutCdnSources(source: string): string {
  const kept = source.split(/,\s*(?=url\(|local\()/).filter(part => !FONT_CDN.test(part.replace(/^url\(\s*["']?/, '')));
  return kept.length ? kept.join(', ') : 'local("Excalidraw font not served")';
}

let running = 0;
let restore: (() => void) | undefined;
/**
 * Runs `work` (Excalidraw's import and export) with its CDN refused, by the two ways Excalidraw reaches it: a `fetch` of a font to inline
 * is refused, and a `FontFace` it creates drops its CDN sources. Every other request and font goes through unchanged. Both are in place
 * only while work runs (counted, for drawings side by side) and are given back after the last one, unless the page replaced them meanwhile.
 */
async function withoutFontCdn<T>(work: () => Promise<T>): Promise<T> {
  if (running++ === 0) {
    const pageFetch = globalThis.fetch, PageFontFace = globalThis.FontFace;
    const fetchGuard = typeof pageFetch === 'function' ? (input: RequestInfo | URL, init?: RequestInit) => {
      const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
      return FONT_CDN.test(url) ? Promise.reject(new TypeError('The drawing viewer does not fetch Excalidraw fonts from its CDN.')) : pageFetch(input, init);
    } : undefined;
    const fontGuard = typeof PageFontFace === 'function' ? new Proxy(PageFontFace, {
      construct: (target, [family, source, descriptors]: ConstructorParameters<typeof FontFace>) =>
        new target(family, typeof source === 'string' ? withoutCdnSources(source) : source, descriptors),
    }) : undefined;
    if (fetchGuard) globalThis.fetch = fetchGuard;
    if (fontGuard) globalThis.FontFace = fontGuard;
    restore = () => {
      if (fetchGuard && globalThis.fetch === fetchGuard) globalThis.fetch = pageFetch;
      if (fontGuard && globalThis.FontFace === fontGuard) globalThis.FontFace = PageFontFace;
    };
  }
  try { return await work(); }
  finally { if (--running === 0) { restore?.(); restore = undefined; } }
}

/** The base URL Excalidraw resolves its fonts against, as the library normalises it. */
function baseOf(assets: string): URL {
  return new URL(`${assets.replace(/\/+$/, '')}/`, globalThis.location?.href);
}

/** Whether the app serves Excalidraw's fonts under `assets` (a font, not an HTML fallback page). */
async function fontsServed(assets: string): Promise<boolean> {
  try {
    const response = await fetch(new URL(FONT_PROBE, baseOf(assets)), { cache: 'force-cache' });
    return response.ok && !/html/i.test(response.headers.get('content-type') ?? '');
  } catch { return false; }
}

/** `point` turned by `angle` (radians, clockwise on screen as Excalidraw draws) around `centre`. */
function turn([x, y]: Point, [cx, cy]: Point, angle: number): Point {
  if (!angle) return [x, y];
  const cos = Math.cos(angle), sin = Math.sin(angle);
  return [cx + (x - cx) * cos - (y - cy) * sin, cy + (x - cx) * sin + (y - cy) * cos];
}

/** A linear element's points on the page: its local points moved to its place and turned by its angle around their own box's centre. */
function pagePoints(element: Element): Point[] {
  const local = element.points ?? [];
  if (!local.length) return [];
  const xs = local.map(([x]) => x), ys = local.map(([, y]) => y);
  const centre: Point = [element.x + (Math.min(...xs) + Math.max(...xs)) / 2, element.y + (Math.min(...ys) + Math.max(...ys)) / 2];
  return local.map(([x, y]) => turn([element.x + x, element.y + y], centre, element.angle ?? 0));
}

/** The scene's shapes and arrows from the restored elements: a container's text is its label, deleted elements are left out. */
export function readExcalidraw(elements: readonly Element[]): { readonly shapes: DrawingShape[]; readonly arrows: DrawingArrow[] } {
  const live = elements.filter(element => !element.isDeleted);
  const bound = new Map(live.filter(element => element.type === 'text' && element.containerId).map(element => [element.containerId!, element.originalText ?? element.text ?? '']));
  const shapes: DrawingShape[] = [], arrows: DrawingArrow[] = [];
  for (const element of live) {
    if (element.type === 'text' && element.containerId && live.some(other => other.id === element.containerId)) continue;
    const label = element.type === 'text' ? element.originalText ?? element.text : bound.get(element.id);
    if (element.type === 'arrow' || element.type === 'line') {
      arrows.push({ id: element.id, kind: element.type, from: element.startBinding?.elementId, to: element.endBinding?.elementId, points: pagePoints(element), label: label || undefined, stroke: colour(element.strokeColor) });
      continue;
    }
    const rotation = element.angle ? Math.round((element.angle * 180 / Math.PI) * 100) / 100 : undefined;
    shapes.push({ id: element.id, kind: element.type, x: element.x, y: element.y, width: element.width, height: element.height, ...(rotation ? { rotation } : {}), label: label || undefined,
      stroke: colour(element.strokeColor), fill: colour(element.backgroundColor), parent: element.frameId ?? undefined });
  }
  return { shapes, arrows };
}

/** Draws an `.excalidraw` file's text; throws a `DrawingError` for a file that is not a scene or draws nothing. */
export async function renderExcalidraw(text: string, { assets }: { readonly assets: string | false }): Promise<RenderedDrawing> {
  let data: unknown;
  try { data = JSON.parse(text); } catch { throw new DrawingError('unreadable', 'The file is not JSON.'); }
  const scene = data as { readonly type?: unknown; readonly elements?: unknown } | null;
  if (!scene || typeof scene !== 'object' || scene.type !== 'excalidraw' || !Array.isArray(scene.elements)) throw new DrawingError('unreadable', 'The file is not an Excalidraw scene.');
  // Where the fonts are must be known before the library loads: its font faces take their sources when it is first imported.
  const own = globalThis.window?.EXCALIDRAW_ASSET_PATH;
  const base = typeof own === 'string' ? own : assets;
  const fonts = base !== false && await fontsServed(base);
  if (fonts && base !== false && own === undefined) window.EXCALIDRAW_ASSET_PATH = baseOf(base).href;
  return withoutFontCdn(() => draw(data, fonts));
}

async function draw(data: unknown, fonts: boolean): Promise<RenderedDrawing> {
  const excalidraw = await import('@excalidraw/excalidraw');
  let restored: ReturnType<typeof excalidraw.restore>;
  try { restored = excalidraw.restore(data as Parameters<typeof excalidraw.restore>[0], null, null); }
  catch (error) { throw new DrawingError('unreadable', String(error)); }
  const elements = restored.elements.filter(element => !element.isDeleted);
  if (!elements.length) throw new DrawingError('empty', 'The scene draws nothing.');
  const exportSvg = (inline: boolean) => excalidraw.exportToSvg({
    elements,
    appState: { ...restored.appState, exportBackground: true, viewBackgroundColor: '#ffffff', exportWithDarkMode: false, exportEmbedScene: false },
    files: restored.files ?? null,
    exportPadding: 16,
    ...(inline ? {} : { skipInliningFonts: true as const }),
  });
  let svg: SVGSVGElement;
  try { svg = await exportSvg(fonts); }
  catch (error) {
    if (!fonts) throw new DrawingError('renderer', String(error));
    svg = await exportSvg(false);
  }
  const read = readExcalidraw(elements as unknown as readonly Element[]);
  // Excalidraw's own bounds of what it drew: each shape's geometry turned by its angle, bound text included.
  const [left, top, right, bottom] = excalidraw.getCommonBounds(elements);
  const width = Number.parseFloat(svg.getAttribute('width') ?? '') || 0, height = Number.parseFloat(svg.getAttribute('height') ?? '') || 0;
  return { svg: new XMLSerializer().serializeToString(svg), width, height, blocked: [],
    drawing: { format: 'excalidraw', bounds: { x: left, y: top, width: right - left, height: bottom - top }, ...read } };
}

// The document of the sandboxed frame in which the official diagrams.net viewer draws a draw.io file (D-1398). The frame is an opaque
// origin (`sandbox="allow-scripts"` only, so it shares nothing with this page) and its Content-Security-Policy allows no network at all and only the
// scripts carrying this frame's nonce: the boot script below and the viewer it inserts. A label's HTML is sanitised by draw.io and, even if
// it carried a handler or a script, the policy refuses it; `mxUtils.eval` (function bodies in a file) fails, since the policy allows no eval.
// The boot script waits for one message from the parent with a port, the viewer's text and the file; it answers once on that port with
// the SVG draw.io exports (`Graph.getSvg`, white page) and what the viewer's own model read, or with an error.

/** The policy of the frame: no fetch, frame, image or font from anywhere but inline data, and only nonce scripts. */
export const drawioPolicy = (nonce: string) =>
  `default-src 'none'; script-src 'nonce-${nonce}'; style-src 'unsafe-inline'; img-src data: blob:; font-src data:; connect-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'none'`;

/** Runs in the frame (ES5, before and after the viewer): reads the model the viewer decoded and exports its SVG. */
const BOOT = String.raw`(function () {
  var nonce = document.currentScript && document.currentScript.nonce, port = null;
  try { window.localStorage; } catch (error) {
    var memory = function () { var items = {}; return { getItem: function (key) { return Object.prototype.hasOwnProperty.call(items, key) ? items[key] : null; },
      setItem: function (key, value) { items[key] = String(value); }, removeItem: function (key) { delete items[key]; }, clear: function () { items = {}; },
      key: function (index) { return Object.keys(items)[index] || null; }, get length() { return Object.keys(items).length; } }; };
    try { Object.defineProperty(window, 'localStorage', { configurable: true, value: memory() }); Object.defineProperty(window, 'sessionStorage', { configurable: true, value: memory() }); } catch (ignored) {}
  }
  window.mxLoadResources = false; window.mxLoadStylesheets = false; window.mxForceIncludes = false;
  var blocked = [];
  document.addEventListener('securitypolicyviolation', function (event) { if (blocked.length < 50) blocked.push(String(event.effectiveDirective || event.violatedDirective) + ' ' + String(event.blockedURI)); });
  function answer(message) { if (port) { port.postMessage(message); port.close(); port = null; } }
  function fail(reason, error) { answer({ type: 'error', reason: reason, message: String(error && error.message || error || reason) }); }
  function plain(value, html) {
    var text = value == null ? '' : String(value);
    if (html) {
      var parsed = new DOMParser().parseFromString(text.replace(/<br\s*\/?>/gi, '\n').replace(/<\/(div|p|li|h[1-6])>/gi, '\n</$1>'), 'text/html');
      var hidden = parsed.querySelectorAll('script, style, template');
      for (var h = 0; h < hidden.length; h++) hidden[h].remove();
      text = parsed.body ? parsed.body.textContent || '' : '';
    }
    return text.replace(/ /g, ' ').replace(/[ \t]+\n/g, '\n').replace(/\n{2,}/g, '\n').trim();
  }
  function colour(value) { return value && value !== 'none' ? String(value) : undefined; }
  function read(graph) {
    var model = graph.getModel(), view = graph.view, scale = view.scale, dx = view.translate.x, dy = view.translate.y, shapes = [], arrows = [], labels = Object.create(null);
    var place = function (state) { return { x: state.x / scale - dx, y: state.y / scale - dy, width: state.width / scale, height: state.height / scale }; };
    var label = function (cell) { return plain(graph.convertValueToString(cell), graph.isHtmlLabel(cell)) || undefined; };
    for (var id in model.cells) {
      var cell = model.cells[id], state = view.getState(cell), parent = model.getParent(cell);
      if (!state || !(model.isVertex(cell) || model.isEdge(cell))) continue;
      if (model.isVertex(cell) && model.isEdge(parent)) { var text = label(cell); if (text) labels[parent.id] = labels[parent.id] ? labels[parent.id] + '\n' + text : text; continue; }
      var style = state.style || {};
      if (model.isEdge(cell)) {
        var source = model.getTerminal(cell, true), target = model.getTerminal(cell, false), points = [];
        for (var i = 0; i < (state.absolutePoints || []).length; i++) { var point = state.absolutePoints[i]; if (point) points.push([point.x / scale - dx, point.y / scale - dy]); }
        // The viewer drops a style value of 'none', so a plain line has neither marker at all.
        var marked = function (marker) { return !!marker && marker !== 'none'; };
        var arrowhead = marked(style.endArrow) || marked(style.startArrow);
        arrows.push({ id: String(cell.id), kind: arrowhead ? 'arrow' : 'line', from: source ? String(source.id) : undefined, to: target ? String(target.id) : undefined, points: points, label: label(cell), stroke: colour(style.strokeColor) });
      } else {
        var box = place(state);
        shapes.push({ id: String(cell.id), kind: String(style.shape || 'rectangle'), x: box.x, y: box.y, width: box.width, height: box.height, label: label(cell),
          stroke: colour(style.strokeColor), fill: colour(style.fillColor), parent: model.isVertex(parent) ? String(parent.id) : undefined });
      }
    }
    for (var a = 0; a < arrows.length; a++) if (labels[arrows[a].id]) arrows[a].label = arrows[a].label ? arrows[a].label + '\n' + labels[arrows[a].id] : labels[arrows[a].id];
    var bounds = graph.getGraphBounds();
    return { format: 'drawio', bounds: { x: bounds.x / scale - dx, y: bounds.y / scale - dy, width: bounds.width / scale, height: bounds.height / scale }, shapes: shapes, arrows: arrows };
  }
  function draw(xml) {
    var document_ = mxUtils.parseXml(xml), root = document_ && document_.documentElement;
    if (!root || ['mxfile', 'mxGraphModel', 'diagram'].indexOf(root.nodeName) < 0) return fail('unreadable', 'not a draw.io file');
    var node;
    try { node = Editor.extractGraphModel(root); } catch (error) { return fail('unreadable', error); }
    if (!node) return fail('unreadable', 'no diagram in the file');
    var graph = new Graph(document.getElementById('graph'));
    graph.setEnabled(false);
    try { new mxCodec(node.ownerDocument).decode(node, graph.getModel()); } catch (error) { return fail('unreadable', error); }
    var drawing = read(graph);
    if (!drawing.shapes.length && !drawing.arrows.length) return fail('empty', 'the diagram draws nothing');
    var svg = graph.getSvg('#ffffff', 1, 16, false, null, true);
    var width = parseFloat(svg.getAttribute('width')) || drawing.bounds.width + 32, height = parseFloat(svg.getAttribute('height')) || drawing.bounds.height + 32;
    var exported = mxUtils.getXml(svg);
    // Refused requests are reported as tasks after the attempt: give them a moment so the answer names what was not drawn.
    setTimeout(function () { answer({ type: 'drawn', svg: exported, width: width, height: height, drawing: drawing, blocked: blocked.slice() }); }, 250);
  }
  window.addEventListener('message', function (event) {
    if (port || event.source !== window.parent || !event.ports || !event.ports[0] || !event.data || event.data.type !== 'draw') return;
    port = event.ports[0];
    try {
      var viewer = document.createElement('script');
      viewer.nonce = nonce; viewer.textContent = String(event.data.viewer);
      document.head.appendChild(viewer);
      if (typeof Graph === 'undefined' || typeof Editor === 'undefined') return fail('renderer', 'the draw.io viewer did not load');
    } catch (error) { return fail('renderer', error); }
    try { draw(String(event.data.xml)); } catch (error) { fail('renderer', error); }
  });
})();`;

/** The frame's whole document for `nonce` (fresh per drawing). */
export function drawioFrameDocument(nonce: string): string {
  return `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="${drawioPolicy(nonce)}">`
    + `<style>html,body{margin:0;background:#fff}#graph{position:absolute;left:0;top:0;width:2000px;height:2000px;overflow:hidden}</style>`
    + `<script nonce="${nonce}">${BOOT}</script></head><body><div id="graph"></div></body></html>`;
}

// A draw.io file drawn by the official diagrams.net viewer (D-1398), vendored and pinned in the kit (`@hachej/boring-ui-kit/drawio-viewer`)
// and run in a hidden sandboxed frame (drawio-frame.ts) that cannot reach the network or this page. The viewer decodes the file (plain or
// compressed `<diagram>`), draws every shape and style as draw.io does and exports the SVG; the frame is removed once it answers. This
// module and the viewer's text load only when a draw.io file opens.
import type { Drawing, DrawingArrow, DrawingShape, RenderedDrawing } from './drawing';
import { DrawingError } from './drawing';
import { drawioFrameDocument } from './drawio-frame';

/** How long the viewer may take to answer before the drawing shows an error. */
const ANSWER_MS = 30000;

const finite = (value: unknown) => typeof value === 'number' && Number.isFinite(value) ? value : 0;
const text = (value: unknown) => typeof value === 'string' && value ? value : undefined;
const list = (value: unknown): readonly Record<string, unknown>[] => Array.isArray(value) ? value.filter(entry => entry && typeof entry === 'object') : [];

/** What the frame read, kept to the fields and types of a `Drawing` (the frame is not trusted to send only those). */
function cleanDrawing(value: unknown): Drawing {
  const raw = (value && typeof value === 'object' ? value : {}) as Record<string, unknown>;
  const bounds = (raw.bounds && typeof raw.bounds === 'object' ? raw.bounds : {}) as Record<string, unknown>;
  const shapes: DrawingShape[] = list(raw.shapes).map(shape => ({ id: String(shape.id), kind: text(shape.kind) ?? 'rectangle', x: finite(shape.x), y: finite(shape.y),
    width: finite(shape.width), height: finite(shape.height), label: text(shape.label), stroke: text(shape.stroke), fill: text(shape.fill), parent: text(shape.parent) }));
  const arrows: DrawingArrow[] = list(raw.arrows).map(arrow => ({ id: String(arrow.id), kind: arrow.kind === 'line' ? 'line' : 'arrow', from: text(arrow.from), to: text(arrow.to),
    points: (Array.isArray(arrow.points) ? arrow.points : []).filter(Array.isArray).map(point => [finite(point[0]), finite(point[1])] as const), label: text(arrow.label), stroke: text(arrow.stroke) }));
  return { format: 'drawio', bounds: { x: finite(bounds.x), y: finite(bounds.y), width: finite(bounds.width), height: finite(bounds.height) }, shapes, arrows };
}

function nonce(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('');
}

/** Draws a `.drawio` file's text; throws a `DrawingError` for a file that is not one, draws nothing or that the viewer could not draw. */
export async function renderDrawio(source: string, { signal }: { readonly signal?: AbortSignal | undefined } = {}): Promise<RenderedDrawing> {
  if (!/<(?:mxfile|mxGraphModel|diagram)\b/.test(source)) throw new DrawingError('unreadable', 'The file is not a draw.io diagram.');
  const { DRAWIO_VIEWER_SCRIPT } = await import('@hachej/boring-ui-kit/drawio-viewer');
  signal?.throwIfAborted();
  const frame = document.createElement('iframe');
  frame.setAttribute('sandbox', 'allow-scripts');
  frame.setAttribute('aria-hidden', 'true');
  frame.setAttribute('data-boring', 'drawio-frame');
  frame.tabIndex = -1;
  frame.title = 'draw.io';
  frame.style.cssText = 'position:fixed;left:-10000px;top:0;width:1200px;height:900px;border:0;visibility:hidden;pointer-events:none';
  frame.srcdoc = drawioFrameDocument(nonce());
  return new Promise<RenderedDrawing>((resolve, reject) => {
    const channel = new MessageChannel();
    const done = () => { clearTimeout(timer); channel.port1.close(); frame.remove(); signal?.removeEventListener('abort', aborted); };
    const aborted = () => { done(); reject(signal?.reason); };
    const timer = setTimeout(() => { done(); reject(new DrawingError('renderer', 'The draw.io viewer did not answer.')); }, ANSWER_MS);
    channel.port1.onmessage = event => {
      const data = (event.data && typeof event.data === 'object' ? event.data : {}) as Record<string, unknown>;
      done();
      const blocked = (Array.isArray(data.blocked) ? data.blocked : []).filter((entry): entry is string => typeof entry === 'string').slice(0, 50);
      if (data.type === 'drawn' && typeof data.svg === 'string') resolve({ svg: data.svg, width: finite(data.width), height: finite(data.height), drawing: cleanDrawing(data.drawing), blocked });
      else reject(new DrawingError(data.reason === 'unreadable' || data.reason === 'empty' ? data.reason : 'renderer', text(data.message)));
    };
    signal?.addEventListener('abort', aborted, { once: true });
    frame.addEventListener('load', () => frame.contentWindow?.postMessage({ type: 'draw', viewer: DRAWIO_VIEWER_SCRIPT, xml: source }, '*', [channel.port2]), { once: true });
    document.body.append(frame);
  });
}

'use client';

// The drawing viewer (D-1398): an Excalidraw or draw.io file, read-only, drawn by the tool's own renderer on a white page fitted to the
// shapes. Excalidraw draws with its library (`exportToSvg`); draw.io with the official diagrams.net viewer in a sandboxed frame without
// network. Each renderer loads the first time a drawing of its format opens. The result is shown as an image from a blob URL, so nothing
// in the file runs on this page, and what the renderer read goes to `onRead` (shapes and arrows, see drawing.ts) for describing it to a model.
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { TriangleAlertIcon } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Spinner } from '@/components/ui/spinner';
import { DrawingError, drawingFormat } from './drawing';
import type { Drawing, DrawingFailure, DrawingFormat, RenderedDrawing } from './drawing';
import { drawingLabelsFor } from './drawing-labels';
import type { DrawingLabels, DrawingLocale } from './drawing-labels';

export { boundsOf, describeDrawing, DrawingError, drawingFormat, isDrawingPath } from './drawing';
export type { Drawing, DrawingArrow, DrawingFailure, DrawingFormat, DrawingShape, RenderedDrawing } from './drawing';
export { defaultDrawingLabels, drawingLabelsFor, frenchDrawingLabels } from './drawing-labels';
export type { DrawingLabels, DrawingLocale } from './drawing-labels';

/** Where the app serves Excalidraw's fonts by default: the package's `dist/prod` folder (its `fonts/` inside) at this path. */
export const DEFAULT_EXCALIDRAW_ASSETS = '/excalidraw/';

export interface DrawingViewerProps {
  /** The file's text. */
  readonly text: string;
  /** The file's path or name: `.excalidraw` or `.drawio` picks the format; without it the text decides. */
  readonly path?: string | undefined;
  /** The format, when the app knows it better than the path. */
  readonly format?: DrawingFormat | undefined;
  /** The drawing's name, for the reader. */
  readonly title?: string | undefined;
  /** Called with what the renderer read once the drawing is drawn, and what it was refused from the network (those parts are not drawn). */
  readonly onRead?: ((drawing: Drawing, details: { readonly blocked: readonly string[] }) => void) | undefined;
  /**
   * The URL of the folder where the app serves `@excalidraw/excalidraw/dist/prod/` (Excalidraw looks for `fonts/` in it), unless the page
   * set `window.EXCALIDRAW_ASSET_PATH` itself. `false`, or a folder that serves no font, draws text without Excalidraw's fonts; the
   * viewer never lets Excalidraw fetch them from its CDN.
   */
  readonly excalidrawAssets?: string | false | undefined;
  /** The base words: English by default. */
  readonly locale?: DrawingLocale | undefined;
  /** Any word over the locale's. */
  readonly labels?: Partial<DrawingLabels> | undefined;
}

type State =
  | { readonly kind: 'loading' }
  | { readonly kind: 'drawn'; readonly rendered: RenderedDrawing; readonly url: string }
  | { readonly kind: 'error'; readonly reason: DrawingFailure };

async function render(format: DrawingFormat, text: string, assets: string | false, signal: AbortSignal): Promise<RenderedDrawing> {
  if (format === 'excalidraw') return (await import('./excalidraw-render')).renderExcalidraw(text, { assets });
  return (await import('./drawio-render')).renderDrawio(text, { signal });
}

/** One drawing; an unreadable or empty file shows an inline error. */
export function DrawingViewer({ text, path, format: given, title, onRead, excalidrawAssets = DEFAULT_EXCALIDRAW_ASSETS, locale, labels: words }: DrawingViewerProps) {
  const labels = useMemo(() => drawingLabelsFor(locale, words), [locale, words]);
  const format = given ?? drawingFormat(path, text);
  // The outcome of the drawing it was rendered for: another text, format or font folder shows loading until its own outcome lands.
  const [outcome, setOutcome] = useState<{ readonly text: string; readonly format: DrawingFormat; readonly assets: string | false; readonly state: State }>();
  const state: State = !format ? { kind: 'error', reason: 'unreadable' }
    : outcome && outcome.text === text && outcome.format === format && outcome.assets === excalidrawAssets ? outcome.state : { kind: 'loading' };
  const read = useRef(onRead);
  useLayoutEffect(() => { read.current = onRead; });
  // A drawn outcome's image lives until another outcome replaces it or the viewer unmounts, so going back to an earlier text never shows a
  // revoked image; that text is drawn again anyway.
  // Every image made is tracked from its creation, so one whose outcome never commits (onRead hid the viewer first) is still released, once.
  const made = useRef(new Set<string>());
  useEffect(() => {
    const url = outcome?.state.kind === 'drawn' ? outcome.state.url : undefined;
    const live = made.current;
    return () => { if (url && live.delete(url)) URL.revokeObjectURL(url); };
  }, [outcome]);
  useEffect(() => { const live = made.current; return () => { for (const url of live) URL.revokeObjectURL(url); live.clear(); }; }, []);
  useEffect(() => {
    if (!format) return;
    const abort = new AbortController();
    render(format, text, excalidrawAssets, abort.signal).then(rendered => {
      if (abort.signal.aborted) return;
      const url = URL.createObjectURL(new Blob([rendered.svg], { type: 'image/svg+xml' }));
      made.current.add(url);
      setOutcome({ text, format, assets: excalidrawAssets, state: { kind: 'drawn', rendered, url } });
      read.current?.(rendered.drawing, { blocked: rendered.blocked });
    }, (error: unknown) => {
      if (abort.signal.aborted) return;
      setOutcome({ text, format, assets: excalidrawAssets, state: { kind: 'error', reason: error instanceof DrawingError ? error.reason : 'renderer' } });
    });
    return () => abort.abort();
  }, [format, text, excalidrawAssets]);
  return <section data-boring="drawing-viewer" data-state={state.kind} data-format={format} data-blocked={state.kind === 'drawn' ? state.rendered.blocked.length : undefined} aria-label={title ?? labels.kind} aria-busy={state.kind === 'loading' || undefined}
    className="flex w-full min-w-0 flex-col gap-3 px-3 pt-2 pb-4 sm:px-6">
    {state.kind === 'loading' && <p role="status" className="m-0 flex items-center justify-center gap-2 p-6 text-sm text-muted-foreground"><Spinner />{labels.loading}</p>}
    {state.kind === 'error' && <Alert variant="destructive" data-testid="drawing-error" data-reason={state.reason}><TriangleAlertIcon aria-hidden="true" />
      <AlertTitle>{labels.errorTitle}</AlertTitle><AlertDescription>{labels.error(state.reason)}</AlertDescription></Alert>}
    {state.kind === 'drawn' && <figure className="m-0 min-w-0 overflow-auto bg-muted p-2">
      <img data-testid="drawing-image" src={state.url} width={Math.round(state.rendered.width) || undefined} height={Math.round(state.rendered.height) || undefined}
        alt={labels.image(state.rendered.drawing.format, state.rendered.drawing.shapes.length, state.rendered.drawing.arrows.length)}
        className="mx-auto block h-auto max-w-full" draggable={false} />
    </figure>}
  </section>;
}

'use client';

import { lazy } from 'react';
import type { ComponentType, ReactNode } from 'react';
import { PenToolIcon } from 'lucide-react';
import { isDrawingPath } from './drawing';
import { drawingLabelsFor } from './drawing-labels';
import type { DrawingLabels, DrawingLocale } from './drawing-labels';

const DrawingViewer = lazy(() => import('./drawing-viewer').then(module => ({ default: module.DrawingViewer })));

/**
 * The artifact kind of a drawing file (structurally an `ArtifactKind` of pi-artifacts): it matches `.excalidraw` and `.drawio` files, names
 * them and draws them with `DrawingViewer`, loaded on first open. It is not in the pi-app-kinds default list: an app that shows drawings
 * adds it to its `artifactKinds` (and installs this item), so apps without drawings never install Excalidraw.
 */
export interface DrawingKind {
  readonly match: (target: { readonly resource: { readonly path: string } }) => boolean;
  readonly label: string;
  readonly icon: ComponentType<{ readonly className?: string; readonly 'aria-hidden'?: boolean | 'true' }>;
  /** Takes the artifact panel's view props (`ArtifactKindViewProps` of pi-artifacts): the file's name comes from `artifact.target`. */
  readonly renderer: (props: { readonly text: string; readonly artifact?: { readonly title?: string | undefined; readonly target: { readonly resource: { readonly path: string } } } | undefined }) => ReactNode;
}

/** A drawing kind in `locale` ("Drawing", "Dessin") with any word overridden, and where the app serves Excalidraw's fonts. */
export function createDrawingKind({ locale, labels, excalidrawAssets }: { readonly locale?: DrawingLocale | undefined; readonly labels?: Partial<DrawingLabels> | undefined; readonly excalidrawAssets?: string | false | undefined } = {}): DrawingKind {
  return {
    match: target => isDrawingPath(target.resource.path),
    label: drawingLabelsFor(locale, labels).kind,
    icon: PenToolIcon,
    renderer: ({ text, artifact }) => <DrawingViewer text={text} path={artifact?.target.resource.path} title={artifact?.title} locale={locale} labels={labels} excalidrawAssets={excalidrawAssets} />,
  };
}

/** The drawing kind, in English, with Excalidraw's fonts at the default path. */
export const drawingKind: DrawingKind = createDrawingKind();
